Q: Getting the motherboard&#39;s serial number A: <p>this code should works on windows 7/10/11:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;string&gt;
#include &lt;format&gt;
#include &lt;Windows.h&gt;

using namespace std;

string get_motherboard_id() {
  // https://learn.microsoft.com/en-us/windows/win32/api/sysinfoapi/nf-sysinfoapi-getsystemfirmwaretable

  string mb_guid;

  // get SMBIOS table size
  DWORD smbiosDataSize = GetSystemFirmwareTable('RSMB', 0, nullptr, 0);
  if (smbiosDataSize == 0) {
    cerr &lt;&lt; &quot;get SMBIOS table size failed&quot;;
  }

  // alloc memory
  std::vector&lt;BYTE&gt; smbiosDataBuffer(smbiosDataSize);
  if (GetSystemFirmwareTable('RSMB', 0, smbiosDataBuffer.data(), smbiosDataSize) != smbiosDataSize) {
    cerr &lt;&lt; &quot;get SMBIOS table failed&quot;;
  }

  // enum SMBIOS structures
  BYTE* p = smbiosDataBuffer.data();
  BYTE* end = p + smbiosDataSize;
  while (p &lt; end) {
    BYTE type = p[0];
    BYTE length = p[1];

    // type 1 is system information, which contains UUID
    if (type == 1 &amp;&amp; length &gt;= 19) {
      // UUID is located at offset 4 in the structure
      BYTE* uuidData = p + 4;

      // pick UUID
      vector&lt;BYTE&gt; temp;
      for (int i = 0; i &lt; length - 4; ++i) {
        temp.emplace_back(static_cast&lt;unsigned&gt;(uuidData[i]));
      }

      // reformat the UUID string to match the &quot;wmic csproduct get uuid&quot; command
      if (temp.size() &gt;= 23) {
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[7])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[6])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[5])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[4])));
        mb_guid.append(&quot;-&quot;);
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[9])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[8])));
        mb_guid.append(&quot;-&quot;);
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[11])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[10])));
        mb_guid.append(&quot;-&quot;);
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[12])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[13])));
        mb_guid.append(&quot;-&quot;);
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[14])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[15])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[16])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[17])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[18])));
        mb_guid.append(format(&quot;{:0&gt;2X}&quot;, (temp[19])));
      }
    }

    // jump to the next structure
    p += length;
    while (p &lt; end &amp;&amp; (p[0] != 0 || p[1] != 0)) {
      p++;
    }
    p += 2; // jump the double zero at the end of the structure
  }

  return mb_guid;
}
</code></pre>

Q: Install express js with npm A: <pre><code>let cart = [];
let total = 0;

fetch(&quot;http://localhost:3000/products&quot;)
.then(res =&gt; res.json())
.then(data =&gt; {
  const productsDiv = document.getElementById(&quot;products&quot;);
  data.forEach(p =&gt; {
    productsDiv.innerHTML += `
      &lt;div class=&quot;product&quot;&gt;
