          &lt;option value=&quot;${p.price_500}&quot;&gt;500g - ${p.price_500} درهم&lt;/option&gt;
          &lt;option value=&quot;${p.price_1000}&quot;&gt;1kg - ${p.price_1000} درهم&lt;/option&gt;
